-- Staged business onboarding, ownership verification, private pre-publication media, and review-first email drips.
-- Applied to production as Supabase migration 20260905025704.

alter table public.business_submissions alter column category drop not null;
alter table public.business_submissions alter column city drop not null;
update public.business_submissions set email=lower(btrim(email)) where email is not null;
alter table public.business_submissions alter column email set not null;
alter table public.business_submissions add column if not exists operating_model text;
alter table public.business_submissions add column if not exists address_text text;
alter table public.business_submissions add column if not exists state text;
alter table public.business_submissions add column if not exists postal_code text;
alter table public.business_submissions add column if not exists hours text;
alter table public.business_submissions add column if not exists price_range text;
alter table public.business_submissions add column if not exists menu_url text;
alter table public.business_submissions add column if not exists ordering_url text;
alter table public.business_submissions add column if not exists reservation_url text;
alter table public.business_submissions add column if not exists profile_data jsonb not null default '{}'::jsonb;
alter table public.business_submissions add column if not exists marketing_opt_in boolean not null default false;
alter table public.business_submissions add column if not exists completed_at timestamptz;
alter table public.business_submissions add column if not exists promoted_business_id uuid references public.businesses(id) on delete set null;
alter table public.business_submissions add column if not exists claim_invited_at timestamptz;
do $$ begin if not exists(select 1 from pg_constraint where conname='business_submissions_operating_model_check') then alter table public.business_submissions add constraint business_submissions_operating_model_check check(operating_model is null or operating_model in('online','storefront','both')); end if; end $$;
create index if not exists business_submissions_promoted_business_idx on public.business_submissions(promoted_business_id);
create index if not exists business_submissions_email_status_idx on public.business_submissions(tenant_id,lower(email),status);

drop policy if exists "public submit business safely" on public.business_submissions;
create policy "public submit business safely" on public.business_submissions for insert to anon,authenticated with check(
 tenant_id is not null and exists(select 1 from public.tenants t where t.id=business_submissions.tenant_id)
 and status='pending' and reviewed_by is null and reviewed_at is null and review_notes is null and promoted_business_id is null and claim_invited_at is null
 and length(btrim(business_name)) between 2 and 200 and length(btrim(phone)) between 7 and 40
 and length(btrim(email)) between 5 and 180 and position('@' in email)>1
 and (category is null or length(btrim(category)) between 2 and 120) and (city is null or length(btrim(city)) between 2 and 120)
 and operating_model in('online','storefront','both') and consent_to_contact=true and source in('public_site','directory_listing_form') and octet_length(profile_data::text)<=30000
);

create table if not exists public.business_submission_media(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,submission_id uuid not null references public.business_submissions(id) on delete cascade,
 storage_path text not null unique,media_type text not null check(media_type in('logo','cover','gallery','menu')),mime_type text not null,original_filename text,alt_text text,caption text,sort_order integer not null default 0,file_size_bytes bigint,
 status text not null default 'pending' check(status in('pending','promoted','archived')),created_at timestamptz not null default now(),promoted_at timestamptz,promoted_business_media_id uuid references public.business_media(id) on delete set null
);
create index if not exists business_submission_media_submission_idx on public.business_submission_media(submission_id,status,sort_order);
alter table public.business_submission_media enable row level security;
create or replace function private.submission_accepts_media(p_tenant uuid,p_submission uuid) returns boolean language sql security definer set search_path='' stable as $$select exists(select 1 from public.business_submissions s where s.id=p_submission and s.tenant_id=p_tenant and s.status='pending' and s.promoted_business_id is null)$$;
revoke all on function private.submission_accepts_media(uuid,uuid) from public; grant execute on function private.submission_accepts_media(uuid,uuid) to anon,authenticated;
create or replace function private.submission_media_path_allowed(p_path text[]) returns boolean language plpgsql security definer set search_path='' stable as $$declare v_tenant uuid;v_submission uuid;begin if coalesce(array_length(p_path,1),0)<3 then return false;end if;if p_path[1]!~*'^[0-9a-f-]{36}$' or p_path[2]!~*'^[0-9a-f-]{36}$' then return false;end if;v_tenant:=p_path[1]::uuid;v_submission:=p_path[2]::uuid;return private.submission_accepts_media(v_tenant,v_submission);exception when others then return false;end$$;
revoke all on function private.submission_media_path_allowed(text[]) from public;grant execute on function private.submission_media_path_allowed(text[]) to anon,authenticated;
create or replace function private.staff_submission_media_path_allowed(p_path text[]) returns boolean language plpgsql security definer set search_path='' stable as $$declare v_tenant uuid;v_uid uuid:=auth.uid();begin if v_uid is null or coalesce(array_length(p_path,1),0)<1 then return false;end if;v_tenant:=p_path[1]::uuid;return exists(select 1 from public.user_roles ur where ur.user_id=v_uid and ur.tenant_id=v_tenant and ur.role in('staff','admin','super_admin'));exception when others then return false;end$$;
revoke all on function private.staff_submission_media_path_allowed(text[]) from public;grant execute on function private.staff_submission_media_path_allowed(text[]) to authenticated;
create policy "public insert submission media" on public.business_submission_media for insert to anon,authenticated with check(status='pending' and promoted_at is null and promoted_business_media_id is null and private.submission_accepts_media(tenant_id,submission_id));
create policy "staff read submission media" on public.business_submission_media for select to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
create policy "staff update submission media" on public.business_submission_media for update to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
create policy "staff delete submission media" on public.business_submission_media for delete to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
grant insert on public.business_submission_media to anon,authenticated;grant select,update,delete on public.business_submission_media to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('business-submission-media','business-submission-media',false,12582912,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "public upload pending business submission media" on storage.objects for insert to anon,authenticated with check(bucket_id='business-submission-media' and private.submission_media_path_allowed(storage.foldername(name)));
create policy "staff read pending business submission media" on storage.objects for select to authenticated using(bucket_id='business-submission-media' and private.staff_submission_media_path_allowed(storage.foldername(name)));
create policy "staff delete pending business submission media" on storage.objects for delete to authenticated using(bucket_id='business-submission-media' and private.staff_submission_media_path_allowed(storage.foldername(name)));

alter table public.business_claims add column if not exists verification_method text;
alter table public.business_claims add column if not exists verification_details text;
alter table public.business_claims add column if not exists verification_url text;
alter table public.business_claims add column if not exists submission_id uuid references public.business_submissions(id) on delete set null;

create table if not exists public.email_drip_campaigns(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,name text not null,slug text not null,audience text not null default 'business_owners',trigger_event text not null default 'business_verified',status text not null default 'draft' check(status in('draft','approved','live','paused','archived')),purpose text,created_by uuid,approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,slug));
create table if not exists public.email_drip_steps(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.email_drip_campaigns(id) on delete cascade,step_order integer not null check(step_order>0),delay_days integer not null default 0 check(delay_days>=0),subject text not null,preheader text,body text not null,cta_label text,cta_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_id,step_order));
create table if not exists public.email_drip_enrollments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,campaign_id uuid not null references public.email_drip_campaigns(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,recipient_email text not null,recipient_name text,status text not null default 'active' check(status in('active','paused','completed','unsubscribed')),next_step_order integer not null default 1,next_send_at timestamptz,last_sent_at timestamptz,enrolled_at timestamptz not null default now(),unique(campaign_id,business_id,recipient_email));
create table if not exists public.email_outbox(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,business_id uuid references public.businesses(id) on delete cascade,recipient_email text not null,recipient_name text,message_type text not null check(message_type in('transactional','drip')),template_key text not null,campaign_id uuid references public.email_drip_campaigns(id) on delete set null,enrollment_id uuid references public.email_drip_enrollments(id) on delete set null,step_id uuid references public.email_drip_steps(id) on delete set null,subject text not null,body text not null,cta_label text,cta_url text,status text not null default 'queued' check(status in('queued','sending','sent','failed','cancelled')),scheduled_for timestamptz not null default now(),sent_at timestamptz,provider_message_id text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists email_outbox_drip_once_idx on public.email_outbox(enrollment_id,step_id) where message_type='drip';create index if not exists email_outbox_queue_idx on public.email_outbox(tenant_id,status,scheduled_for);
alter table public.email_drip_campaigns enable row level security;alter table public.email_drip_steps enable row level security;alter table public.email_drip_enrollments enable row level security;alter table public.email_outbox enable row level security;
create policy "tenant staff manage email_drip_campaigns" on public.email_drip_campaigns for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
create policy "tenant staff manage email_drip_enrollments" on public.email_drip_enrollments for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
create policy "tenant staff manage email_outbox" on public.email_outbox for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]));
create policy "tenant staff manage email drip steps" on public.email_drip_steps for all to authenticated using(exists(select 1 from public.email_drip_campaigns c where c.id=email_drip_steps.campaign_id and private.has_tenant_role(c.tenant_id,array['staff','admin','super_admin']::text[]))) with check(exists(select 1 from public.email_drip_campaigns c where c.id=email_drip_steps.campaign_id and private.has_tenant_role(c.tenant_id,array['staff','admin','super_admin']::text[])));
grant select,insert,update,delete on public.email_drip_campaigns,public.email_drip_steps,public.email_drip_enrollments,public.email_outbox to authenticated;

create or replace function public.get_claimable_business(p_business_id uuid) returns table(id uuid,name text,status text,phone text,email text,website text,operating_model text) language plpgsql security definer set search_path='' as $$declare v_uid uuid:=auth.uid();v_email text:=lower(coalesce(auth.jwt()->>'email',''));begin if v_uid is null then raise exception 'authentication_required';end if;return query select b.id,b.name,b.status,b.phone,b.email,b.website,coalesce(s.operating_model,'') from public.businesses b left join lateral(select s1.operating_model,s1.email from public.business_submissions s1 where s1.promoted_business_id=b.id and s1.status='approved' order by s1.reviewed_at desc nulls last limit 1)s on true where b.id=p_business_id and b.tenant_id=(select t.id from public.tenants t where t.slug='central-illinois-local-pros' limit 1) and b.claimed=false and(b.status='published' or(b.status='pending' and lower(coalesce(s.email,''))=v_email));end$$;
revoke all on function public.get_claimable_business(uuid) from public,anon;grant execute on function public.get_claimable_business(uuid) to authenticated;

create or replace function public.submit_business_ownership_claim(p_business_id uuid,p_claimant_name text,p_claimant_role text,p_verification_method text,p_verification_details text,p_verification_url text default null,p_phone text default null) returns uuid language plpgsql set search_path='' as $$declare v_id uuid;v_uid uuid:=auth.uid();v_email text:=lower(coalesce(auth.jwt()->>'email',''));v_business public.businesses%rowtype;v_submission_id uuid;v_method text:=lower(trim(coalesce(p_verification_method,'')));begin if v_uid is null then raise exception 'authentication_required';end if;if char_length(trim(coalesce(p_claimant_name,'')))<2 then raise exception 'claimant_name_required';end if;if char_length(v_email)<5 or position('@' in v_email)<2 then raise exception 'account_email_required';end if;if v_method not in('business_email','listed_phone','official_website','registration_license','business_document','official_social','other') then raise exception 'verification_method_required';end if;if char_length(trim(coalesce(p_verification_details,'')))<10 then raise exception 'verification_details_required';end if;select * into v_business from public.businesses where id=p_business_id;if not found then raise exception 'business_not_found';end if;if v_business.claimed then raise exception 'business_already_claimed';end if;if v_business.status='pending' then select s.id into v_submission_id from public.business_submissions s where s.promoted_business_id=p_business_id and s.status='approved' and lower(s.email)=v_email order by s.reviewed_at desc nulls last limit 1;if v_submission_id is null then raise exception 'claim_invitation_email_mismatch';end if;elsif v_business.status<>'published' then raise exception 'business_not_claimable';end if;if exists(select 1 from public.business_claims c where c.business_id=p_business_id and c.claimant_user_id=v_uid and c.status in('pending','in_review','approved')) then raise exception 'claim_already_submitted';end if;insert into public.business_claims(business_id,claimant_user_id,claimant_name,claimant_role,email,phone,status,verification_method,verification_details,verification_url,submission_id) values(p_business_id,v_uid,trim(p_claimant_name),nullif(trim(p_claimant_role),''),v_email,nullif(trim(coalesce(p_phone,'')),''),'pending',v_method,trim(p_verification_details),nullif(trim(coalesce(p_verification_url,'')),''),v_submission_id) returning id into v_id;return v_id;end$$;
revoke all on function public.submit_business_ownership_claim(uuid,text,text,text,text,text,text) from public,anon;grant execute on function public.submit_business_ownership_claim(uuid,text,text,text,text,text,text) to authenticated;

create or replace function public.submit_business_claim(p_business_id uuid,p_claimant_name text,p_claimant_role text,p_email text,p_phone text default null) returns uuid language plpgsql set search_path='' as $$begin if auth.uid() is null then raise exception 'authentication_required';end if;if lower(trim(coalesce(p_email,'')))<>lower(coalesce(auth.jwt()->>'email','')) then raise exception 'account_email_mismatch';end if;return public.submit_business_ownership_claim(p_business_id,p_claimant_name,p_claimant_role,'other','Legacy claim submission. Staff must obtain additional ownership evidence before approval.',null,p_phone);end$$;

create or replace function public.review_business_submission(p_submission_id uuid,p_decision text,p_notes text default null) returns jsonb language plpgsql set search_path='' as $$
declare v_sub public.business_submissions%rowtype;v_actor uuid:=auth.uid();v_decision text:=lower(trim(coalesce(p_decision,'')));v_category_id uuid;v_location_id uuid;v_business_id uuid;v_slug text;v_base_slug text;v_physical boolean:=false;v_location_name text;
begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_sub from public.business_submissions where id=p_submission_id for update;if not found then raise exception 'submission_not_found';end if;if not private.has_tenant_role(v_sub.tenant_id,array['staff','admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('approve','reject') then raise exception 'invalid_decision';end if;if v_decision='reject' then update public.business_submissions set status='rejected',reviewed_by=v_actor,reviewed_at=now(),review_notes=nullif(trim(coalesce(p_notes,'')),'') where id=p_submission_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_sub.tenant_id,v_actor,'business_submission_rejected','Rejected business submission '||p_submission_id::text||' for '||v_sub.business_name);return jsonb_build_object('ok',true,'submission_id',p_submission_id,'decision','reject');end if;if v_sub.status<>'pending' then raise exception 'submission_not_pending';end if;
if nullif(trim(coalesce(v_sub.category,'')),'') is not null then select c.id into v_category_id from public.categories c where c.tenant_id=v_sub.tenant_id and c.is_active=true and lower(c.name)=lower(trim(v_sub.category)) limit 1;if v_category_id is null then raise exception 'category_not_found';end if;end if;
if nullif(trim(coalesce(v_sub.city,'')),'') is not null then select l.id,l.name into v_location_id,v_location_name from public.locations l where l.tenant_id=v_sub.tenant_id and l.is_active=true and l.type in('city','town') and lower(l.name)=lower(trim(v_sub.city)) order by l.name limit 1;if v_location_id is null then raise exception 'location_not_found';end if;end if;
if exists(select 1 from public.businesses b where b.tenant_id=v_sub.tenant_id and(lower(trim(b.name))=lower(trim(v_sub.business_name)) or trim(b.phone)=trim(v_sub.phone) or(nullif(trim(v_sub.website),'') is not null and lower(trim(coalesce(b.website,'')))=lower(trim(v_sub.website))))) then raise exception 'possible_duplicate_business';end if;
v_base_slug:=trim(both '-' from lower(regexp_replace(v_sub.business_name||coalesce('-'||nullif(v_sub.city,''),'')||'-il','[^a-zA-Z0-9]+','-','g')));v_slug:=v_base_slug;if exists(select 1 from public.businesses b where b.tenant_id=v_sub.tenant_id and b.slug=v_slug) then v_slug:=v_base_slug||'-'||substr(p_submission_id::text,1,8);end if;v_physical:=v_sub.operating_model in('storefront','both') and nullif(trim(coalesce(v_sub.address_text,'')),'') is not null and v_location_id is not null;
insert into public.businesses(tenant_id,slug,name,primary_location_id,phone,email,website,description,hours,status,published_at,claimed,verified,featured,rating,review_count,price_range,menu_url,ordering_url,reservation_url,address_text,source_name,source_url,source_checked_at,attributes) values(v_sub.tenant_id,v_slug,trim(v_sub.business_name),case when v_physical then v_location_id else null end,trim(v_sub.phone),lower(trim(v_sub.email)),nullif(trim(v_sub.website),''),nullif(trim(v_sub.description),''),nullif(trim(v_sub.hours),''),'pending',null,false,false,false,0,0,nullif(trim(v_sub.price_range),''),nullif(trim(v_sub.menu_url),''),nullif(trim(v_sub.ordering_url),''),nullif(trim(v_sub.reservation_url),''),case when v_physical then nullif(trim(v_sub.address_text),'') else null end,'Business Submission',case when nullif(trim(v_sub.website),'') is not null then trim(v_sub.website) else null end,case when nullif(trim(v_sub.website),'') is not null then now() else null end,jsonb_build_object('submission_id',p_submission_id,'submission_source',v_sub.source,'operating_model',v_sub.operating_model,'submitted_profile',coalesce(v_sub.profile_data,'{}'::jsonb))) returning id into v_business_id;
if v_category_id is not null then insert into public.business_categories(business_id,category_id,is_primary) values(v_business_id,v_category_id,true);end if;
if v_physical then insert into public.business_locations(tenant_id,business_id,location_id,label,location_type,is_primary,is_active,verified,address_text,city,state,postal_code,phone,email,source_name,source_url,source_checked_at) values(v_sub.tenant_id,v_business_id,v_location_id,'Primary Location','storefront',true,true,false,trim(v_sub.address_text),v_location_name,coalesce(nullif(trim(v_sub.state),''),'IL'),nullif(trim(v_sub.postal_code),''),trim(v_sub.phone),lower(trim(v_sub.email)),'Business Submission',case when nullif(trim(v_sub.website),'') is not null then trim(v_sub.website) else null end,case when nullif(trim(v_sub.website),'') is not null then now() else null end);end if;
insert into public.business_service_areas(business_id,location_id) select v_business_id,l.id from public.locations l where l.tenant_id=v_sub.tenant_id and l.is_active=true and exists(select 1 from unnest(coalesce(v_sub.service_areas,'{}'::text[])) a where lower(trim(a))=lower(l.name)) on conflict do nothing;
update public.business_submissions set status='approved',reviewed_by=v_actor,reviewed_at=now(),review_notes=nullif(trim(coalesce(p_notes,'')),''),promoted_business_id=v_business_id,claim_invited_at=now() where id=p_submission_id;
insert into public.email_outbox(tenant_id,business_id,recipient_email,recipient_name,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(v_sub.tenant_id,v_business_id,lower(v_sub.email),coalesce(nullif(v_sub.contact_name,''),v_sub.business_name),'transactional','business_submission_approved','Your business profile is approved for ownership review','We approved the directory profile information for '||v_sub.business_name||'. The profile is not public yet. Sign in or create an account with this email address, then submit your ownership evidence. After ownership and final verification are approved, the profile can be published.','Claim Your Business','/claim?business='||v_business_id::text,'queued',now());
insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_sub.tenant_id,v_actor,'business_submission_approved_pending_claim','Approved business submission '||p_submission_id::text||' and created pending business '||v_business_id::text||' for ownership review.');return jsonb_build_object('ok',true,'submission_id',p_submission_id,'decision','approve','business_id',v_business_id,'slug',v_slug,'status','pending','claim_invited',true);end$$;

create or replace function public.review_business_claim(p_claim_id uuid,p_decision text,p_notes text default null) returns jsonb language plpgsql set search_path='' as $$declare v_claim public.business_claims%rowtype;v_business public.businesses%rowtype;v_actor uuid:=auth.uid();v_claimant_user uuid;v_decision text:=lower(trim(coalesce(p_decision,'')));begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_claim from public.business_claims where id=p_claim_id for update;if not found then raise exception 'claim_not_found';end if;select * into v_business from public.businesses where id=v_claim.business_id;if not found then raise exception 'business_not_found';end if;if not private.has_tenant_role(v_business.tenant_id,array['staff','admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('approve','reject') then raise exception 'invalid_decision';end if;if v_decision='approve' then v_claimant_user:=v_claim.claimant_user_id;if v_claimant_user is null then raise exception 'claimant_account_required';end if;if nullif(trim(coalesce(v_claim.verification_method,'')),'') is null or char_length(trim(coalesce(v_claim.verification_details,'')))<10 then raise exception 'ownership_evidence_required';end if;insert into public.business_owners(business_id,user_id,ownership_role) values(v_claim.business_id,v_claimant_user,'owner') on conflict(business_id,user_id) do update set ownership_role=excluded.ownership_role;update public.business_claims set status='approved',reviewed_by=v_actor,reviewed_at=now(),review_notes=nullif(trim(coalesce(p_notes,'')),'') where id=p_claim_id;update public.businesses set claimed=true,updated_at=now() where id=v_claim.business_id;insert into public.notifications(user_id,tenant_id,title,body,action_url,event_key) values(v_claimant_user,v_business.tenant_id,'Ownership approved','Your ownership claim for '||v_business.name||' was approved. Final business verification is the next publication gate.','/business-portal','business_claim_approved:'||v_claim.business_id::text);insert into public.email_outbox(tenant_id,business_id,recipient_email,recipient_name,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(v_business.tenant_id,v_business.id,lower(v_claim.email),v_claim.claimant_name,'transactional','business_claim_approved','Your ownership claim was approved','Your ownership claim for '||v_business.name||' was approved. The listing is now marked Claimed. Final directory verification is still required before a new pending profile is published.','Open Business Portal','/business-portal','queued',now());insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,'business_claim_approved','Approved ownership claim '||p_claim_id::text||' for business '||v_claim.business_id::text);else update public.business_claims set status='rejected',reviewed_by=v_actor,reviewed_at=now(),review_notes=nullif(trim(coalesce(p_notes,'')),'') where id=p_claim_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,'business_claim_rejected','Rejected ownership claim '||p_claim_id::text||' for business '||v_claim.business_id::text);end if;return jsonb_build_object('ok',true,'claim_id',p_claim_id,'decision',v_decision,'business_id',v_claim.business_id,'claimant_user_id',v_claimant_user);end$$;

create or replace function private.enroll_business_drips(p_business_id uuid) returns integer language plpgsql set search_path='' as $$declare v_business public.businesses%rowtype;v_email text;v_name text;v_count integer:=0;v_campaign record;v_delay integer;begin select * into v_business from public.businesses where id=p_business_id;if not found then return 0;end if;select s.email,coalesce(nullif(s.contact_name,''),s.business_name) into v_email,v_name from public.business_submissions s where s.promoted_business_id=p_business_id and s.status='approved' and s.marketing_opt_in=true order by s.reviewed_at desc nulls last,s.created_at desc limit 1;if v_email is null then return 0;end if;for v_campaign in select c.id from public.email_drip_campaigns c where c.tenant_id=v_business.tenant_id and c.trigger_event='business_verified' and c.status='live' loop select coalesce(min(delay_days),0) into v_delay from public.email_drip_steps where campaign_id=v_campaign.id and is_active=true;insert into public.email_drip_enrollments(tenant_id,campaign_id,business_id,recipient_email,recipient_name,status,next_step_order,next_send_at) values(v_business.tenant_id,v_campaign.id,p_business_id,lower(v_email),v_name,'active',1,now()+make_interval(days=>v_delay)) on conflict(campaign_id,business_id,recipient_email) do nothing;if found then v_count:=v_count+1;end if;end loop;return v_count;end$$;

create or replace function public.review_business_verification(p_business_id uuid,p_decision text,p_source_name text default null,p_source_url text default null) returns jsonb language plpgsql set search_path='' as $$declare v_business public.businesses%rowtype;v_actor uuid:=auth.uid();v_decision text:=lower(trim(coalesce(p_decision,'')));v_source_name text;v_source_url text;v_email text;v_name text;v_user uuid;v_was_pending boolean:=false;v_enrolled integer:=0;begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_business from public.businesses where id=p_business_id for update;if not found then raise exception 'business_not_found';end if;if not private.has_tenant_role(v_business.tenant_id,array['admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('verify','unverify') then raise exception 'invalid_decision';end if;if v_decision='verify' then if v_business.status not in('pending','published') then raise exception 'pending_or_published_business_required';end if;v_was_pending:=v_business.status='pending';if v_was_pending then if not v_business.claimed then raise exception 'claim_required_before_publication';end if;if not exists(select 1 from public.business_claims c where c.business_id=p_business_id and c.status='approved') then raise exception 'approved_ownership_claim_required';end if;end if;v_source_name:=nullif(trim(coalesce(p_source_name,v_business.source_name,'')),'');v_source_url:=nullif(trim(coalesce(p_source_url,v_business.source_url,'')),'');if v_source_name is null or v_source_url is null then raise exception 'verification_source_required';end if;if v_source_url!~*'^https?://' then raise exception 'verification_source_url_invalid';end if;update public.businesses set verified=true,status=case when v_was_pending then 'published' else status end,published_at=case when v_was_pending then coalesce(published_at,now()) else published_at end,source_name=v_source_name,source_url=v_source_url,source_checked_at=now(),updated_at=now() where id=p_business_id;select c.email,c.claimant_name,c.claimant_user_id into v_email,v_name,v_user from public.business_claims c where c.business_id=p_business_id and c.status='approved' order by c.reviewed_at desc nulls last,c.created_at desc limit 1;if v_email is not null then insert into public.email_outbox(tenant_id,business_id,recipient_email,recipient_name,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(v_business.tenant_id,p_business_id,lower(v_email),v_name,'transactional','business_verified_published','Your business is verified'||case when v_was_pending then ' and live' else '' end,'Great news — '||v_business.name||' has completed directory verification.'||case when v_was_pending then ' Your business profile is now published on Central Illinois Local Pros.' else ' The Verified trust signal is now active on your published listing.' end,'View Your Business','/business/'||v_business.slug,'queued',now());end if;if v_user is not null then insert into public.notifications(user_id,tenant_id,title,body,action_url,event_key) values(v_user,v_business.tenant_id,'Business verified'||case when v_was_pending then ' and published' else '' end,v_business.name||' completed directory verification.','/business/'||v_business.slug,'business_verified:'||p_business_id::text);end if;v_enrolled:=private.enroll_business_drips(p_business_id);insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,case when v_was_pending then 'business_verified_and_published' else 'business_verified' end,'Verified business '||p_business_id::text||' using documented source evidence.'||case when v_was_pending then ' Published after approved ownership claim.' else '' end);else update public.businesses set verified=false,source_checked_at=now(),updated_at=now() where id=p_business_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,'business_unverified','Removed verification from business '||p_business_id::text||'.');end if;return jsonb_build_object('ok',true,'business_id',p_business_id,'decision',v_decision,'verified',v_decision='verify','drip_enrollments',v_enrolled);end$$;

with tenant as(select id from public.tenants where slug='central-illinois-local-pros' limit 1) insert into public.email_drip_campaigns(tenant_id,name,slug,audience,trigger_event,status,purpose) select id,'Sponsored Placement Education','sponsored-placement-education','verified_business_owners','business_verified','draft','Educate verified business owners about clearly labeled Featured/Sponsored visibility without implying that payment changes organic rank or verification.' from tenant on conflict(tenant_id,slug) do nothing;
with tenant as(select id from public.tenants where slug='central-illinois-local-pros' limit 1) insert into public.email_drip_campaigns(tenant_id,name,slug,audience,trigger_event,status,purpose) select id,'Skylight Local Growth Education','skylight-local-growth-education','verified_business_owners','business_verified','draft','Educational Skylight Reflections Marketing follow-up covering local SEO, Google Business Profile quality, websites, conversion and qualified-lead systems without ranking or lead guarantees.' from tenant on conflict(tenant_id,slug) do nothing;
insert into public.email_drip_steps(campaign_id,step_order,delay_days,subject,preheader,body,cta_label,cta_url) select c.id,v.* from public.email_drip_campaigns c join(values
(1,2,'Your business is live — what Sponsored placement actually changes','Paid visibility is separate from organic rank.','Your Central Illinois Local Pros profile is verified and live. Sponsored placement can put a clearly labeled business card in additional high-visibility areas of the directory. It does not buy a better organic position, change verification, or guarantee leads.','See Visibility Options','/for-businesses'),
(2,5,'Be seen where local customers are already browsing','Reach shoppers inside relevant directory pages.','Featured and Sponsored placements are designed for businesses that want additional exposure while people are already browsing local categories, cities, and business profiles. The placement stays clearly labeled as advertising.','Explore Sponsored Placement','/for-businesses'),
(3,9,'Make your profile convert before buying more visibility','Strong profiles help customers understand the business faster.','Before adding paid visibility, review your logo, photos, business description, hours, service areas, website and calls to action. Better profile information can make every visit more useful without changing organic ranking rules.','Review Business Options','/for-businesses'),
(4,14,'Want to explore Featured or Sponsored placement?','Choose visibility only when it fits your goals.','If additional directory exposure fits your goals, you can review Featured and Sponsored options. Paid placement remains separate from verification, organic relevance and lead guarantees.','Ask About Visibility','/contact?reason=visibility-plan&plan=featured&source=email-drip'))v(step_order,delay_days,subject,preheader,body,cta_label,cta_url) on c.slug='sponsored-placement-education' on conflict(campaign_id,step_order) do nothing;
insert into public.email_drip_steps(campaign_id,step_order,delay_days,subject,preheader,body,cta_label,cta_url) select c.id,v.* from public.email_drip_campaigns c join(values
(1,3,'3 local SEO gaps that can cost a business visibility','A practical checklist from Skylight Reflections Marketing.','Local visibility usually starts with consistent business information, useful location-focused website content, and a well-maintained Google Business Profile. Skylight Reflections Marketing can help identify gaps and prioritize improvements, but no agency can guarantee a specific Google ranking.','Review Growth Options','/contact?reason=visibility-plan&plan=marketing_review&source=email-drip'),
(2,7,'Your Google Business Profile and local search visibility','Accuracy, relevance and activity matter.','Your Google Business Profile is often one of the first places local customers encounter your business. Accurate categories, services, hours, photos, reviews and website alignment can strengthen the overall local-search presence.','Request a Visibility Review','/contact?reason=visibility-plan&plan=marketing_review&source=email-drip'),
(3,12,'Turn more website visits into qualified inquiries','Traffic is only useful when the next step is clear.','For lead-based businesses, a website should make it easy to understand services, service areas, trust signals and the next action. Skylight can help improve landing pages, local SEO structure and lead-capture paths around the customers you actually want.','Explore Lead Growth Help','/contact?reason=visibility-plan&plan=marketing_review&source=email-drip'),
(4,18,'What to improve before paying for more traffic','Fix conversion and local visibility foundations first.','Before adding more paid traffic, review whether your website, Google Business Profile, directory profile and contact flow are ready to convert attention into real inquiries. Improving the foundation can make future marketing spend more useful.','See Marketing Support','/contact?reason=visibility-plan&plan=marketing_review&source=email-drip'),
(5,25,'Want a Skylight Reflections Marketing visibility review?','Review SEO, Google visibility and lead-generation opportunities.','If you want a second set of eyes on your local visibility, Skylight Reflections Marketing can review the business website, local SEO foundation, Google Business Profile and lead-generation opportunities, then recommend practical next steps.','Request a Review','/contact?reason=visibility-plan&plan=marketing_review&source=email-drip'))v(step_order,delay_days,subject,preheader,body,cta_label,cta_url) on c.slug='skylight-local-growth-education' on conflict(campaign_id,step_order) do nothing;
